        if in_s {
            vis_s[cur] = true;
            if let Some(n) = nodes[cur].neighbor {
                vis_c[n] = true;
            }
        } else {
            vis_c[cur] = true;
            if let Some(n) = nodes[cur].neighbor {
                vis_s[n] = true;
            }
        }
        match nodes[cur].neighbor {
            Some(nidx) => {
                in_s = !in_s;
                cur = nidx;
            }
            None => break,
        }
