131	/// Rounds a floating-point point to the integer grid, matching
132	/// Clipper2's round-to-nearest grid snapping of intersection vertices.
133	pub fn round_point(pt: (f64, f64)) -> Point64 {
134	    Point64::new(pt.0.round() as i64, pt.1.round() as i64)
135	}
