1	//! Boolean polygon operations (intersect / union / difference / xor) for
2	//! simple, non-self-intersecting polygons with integer vertices.
3	//!
4	//! Algorithm: Greiner–Hormann. Both polygons are converted to circular
5	//! doubly-linked vertex lists, edge crossings are computed in `f64`, rounded
6	//! to the nearest `i64` (Clipper2 rounds to the grid) and inserted into both
7	//! lists; the crossings are then classified entry/exit and result polygons
8	//! are traced according to the requested operation.
9	//!
10	//! Limitations (by design): holes are ignored — every input path is treated
11	//! as one simple outer polygon — and vertex-touch / collinear-overlap
12	//! degeneracies are skipped rather than resolved with Clipper2 parity.
13	//! `FillRule` is accepted for API compatibility: for simple polygons all
14	//! fill rules agree, so it does not change the result.
15	//!
16	//! Output convention: result polygons are counter-clockwise (positive area).
17	
18	use crate::geom::{area, FillRule, Path64, Paths64, Point64};
19	
20	/// One vertex in a circular doubly-linked polygon list.
21	#[derive(Clone)]
22	struct Node {
23	    pt: Point64,
24	    next: usize,
25	    prev: usize,
26	    /// Matching crossing node in the other polygon's list.
27	    neighbor: Option<usize>,
28	    /// True for nodes inserted at edge crossings.
29	    intersect: bool,
30	    /// True if the polygon enters the other polygon's interior here.
31	    entry: bool,
32	}
33	
34	/// A proper (edge-interior) crossing between a subject and a clip edge.
35	struct Cross {
36	    pt: Point64,
37	    s_edge: usize,
38	    t: f64,
39	    c_edge: usize,
40	    u: f64,
41	}
42	
43	/// Compute the crossing of segments a1->a2 and b1->b2 in `f64`.
44	/// Returns the edge parameters (t, u) and the grid-rounded point, or `None`
45	/// for parallel/collinear segments and crossings at segment endpoints
46	/// (vertex-touch degeneracies are skipped defensively).
47	fn seg_intersect(a1: Point64, a2: Point64, b1: Point64, b2: Point64) -> Option<(f64, f64, Point64)> {
48	    let d = (a2.x - a1.x) as f64 * (b2.y - b1.y) as f64
49	        - (a2.y - a1.y) as f64 * (b2.x - b1.x) as f64;
50	    if d.abs() < 1e-12 {
51	        return None; // parallel or collinear
52	    }
53	    let t = ((b1.x - a1.x) as f64 * (b2.y - b1.y) as f64
54	        - (b1.y - a1.y) as f64 * (b2.x - b1.x) as f64)
55	        / d;
56	    let u = ((b1.x - a1.x) as f64 * (a2.y - a1.y) as f64
57	        - (b1.y - a1.y) as f64 * (a2.x - a1.x) as f64)
58	        / d;
59	    const EPS: f64 = 1e-9;
60	    if t <= EPS || t >= 1.0 - EPS || u <= EPS || u >= 1.0 - EPS {
61	        return None; // crossing at an endpoint: degenerate, skip
62	    }
63	    let x = a1.x as f64 + t * (a2.x - a1.x) as f64;
64	    let y = a1.y as f64 + t * (a2.y - a1.y) as f64;
65	    Some((t, u, Point64::new(x.round() as i64, y.round() as i64)))
66	}
67	
68	/// Even-odd point-in-polygon test, exact via 128-bit integer arithmetic.
69	fn point_in_path(p: Point64, path: &Path64) -> bool {
70	    let mut inside = false;
71	    let n = path.len();
72	    for i in 0..n {
73	        let a = path[i];
74	        let b = path[(i + 1) % n];
75	        if (a.y > p.y) != (b.y > p.y) {
76	            // Is p.x left of the edge's x at height p.y? Compare without division.
77	            let lhs = (p.x as i128 - a.x as i128) * (b.y as i128 - a.y as i128);
78	            let rhs = (b.x as i128 - a.x as i128) * (p.y as i128 - a.y as i128);
79	            let crosses = if b.y > a.y { lhs < rhs } else { lhs > rhs };
80	            if crosses {
81	                inside = !inside;
82	            }
83	        }
84	    }
85	    inside
86	}
87	
88	/// Both linked lists plus everything the tracer needs.
89	struct PairData {
90	    s: Vec<Node>,
91	    c: Vec<Node>,
92	}
93	
94	/// Build the two circular lists with all crossings inserted and classified.
95	fn build_lists(subj: &Path64, clip: &Path64) -> PairData {
96	    let ns = subj.len();
97	    let nc = clip.len();
98	
99	    // 1. Find all proper edge crossings.
100	    let mut crosses: Vec<Cross> = Vec::new();
101	    for i in 0..ns {
102	        let (a1, a2) = (subj[i], subj[(i + 1) % ns]);
103	        if a1 == a2 {
104	            continue; // zero-length edge guard
105	        }
106	        for j in 0..nc {
107	            let (b1, b2) = (clip[j], clip[(j + 1) % nc]);
108	            if b1 == b2 {
109	                continue;
110	            }
111	            if let Some((t, u, pt)) = seg_intersect(a1, a2, b1, b2) {
112	                crosses.push(Cross { pt, s_edge: i, t, c_edge: j, u });
113	            }
114	        }
115	    }
116	
117	    // 2. Lay out each list in polygon order: vertex i, then its edge's
118	    //    crossings sorted by edge parameter. Node index == list order.
119	    let mut s: Vec<Node> = Vec::new();
120	    let mut c: Vec<Node> = Vec::new();
121	    let mut s_loc = vec![usize::MAX; crosses.len()];
122	    let mut c_loc = vec![usize::MAX; crosses.len()];
123	
124	    let plain = |pt: Point64| Node { pt, next: 0, prev: 0, neighbor: None, intersect: false, entry: false };
125	    let xnode = |pt: Point64| Node { pt, next: 0, prev: 0, neighbor: None, intersect: true, entry: false };
126	
127	    for i in 0..ns {
128	        s.push(plain(subj[i]));
129	        let mut ids: Vec<usize> = (0..crosses.len()).filter(|&k| crosses[k].s_edge == i).collect();
130	        ids.sort_by(|&a, &b| crosses[a].t.partial_cmp(&crosses[b].t).unwrap());
131	        for k in ids {
132	            s_loc[k] = s.len();
133	            s.push(xnode(crosses[k].pt));
134	        }
135	    }
136	    for j in 0..nc {
137	        c.push(plain(clip[j]));
138	        let mut ids: Vec<usize> = (0..crosses.len()).filter(|&k| crosses[k].c_edge == j).collect();
139	        ids.sort_by(|&a, &b| crosses[a].u.partial_cmp(&crosses[b].u).unwrap());
140	        for k in ids {
141	            c_loc[k] = c.len();
142	            c.push(xnode(crosses[k].pt));
143	        }
144	    }
145	
146	    // 3. Circular next/prev links (list order == vec order by construction).
147	    let link = |nodes: &mut Vec<Node>| {
148	        let n = nodes.len();
149	        for i in 0..n {
150	            nodes[i].next = (i + 1) % n;
151	            nodes[i].prev = (i + n - 1) % n;
152	        }
153	    };
154	    link(&mut s);
155	    link(&mut c);
156	
157	    // 4. Pair up matching crossings.
158	    for k in 0..crosses.len() {
159	        let (si, ci) = (s_loc[k], c_loc[k]);
160	        s[si].neighbor = Some(ci);
161	        c[ci].neighbor = Some(si);
162	    }
163	
164	    // 5. Classify crossings entry/exit by alternating, seeded from whether
165	    //    each polygon's first vertex lies inside the other polygon.
166	    let mark = |nodes: &mut Vec<Node>, mut inside: bool| {
167	        for node in nodes.iter_mut() {
168	            if node.intersect {
169	                node.entry = !inside;
170	                inside = !inside;
171	            }
172	        }
173	    };
174	    let s0_inside = point_in_path(subj[0], clip);
175	    let c0_inside = point_in_path(clip[0], subj);
176	    mark(&mut s, s0_inside);
177	    mark(&mut c, c0_inside);
178	
179	    PairData { s, c }
180	}
181	
182	/// Append a vertex, dropping consecutive duplicates (from grid rounding).
183	fn push_pt(poly: &mut Path64, pt: Point64) {
184	    if poly.last() != Some(&pt) {
185	        poly.push(pt);
186	    }
187	}
188	
189	/// Trace one result polygon starting at crossing `start` of the subject list.
190	/// Direction at each crossing: entry -> forward, exit -> backward (in the
191	/// list currently being walked). `s_entry`/`c_entry` are the *effective*
192	/// (possibly inverted) entry flags for the operation being computed.
193	fn trace(
194	    s: &[Node],
195	    c: &[Node],
196	    s_entry: &[bool],
197	    c_entry: &[bool],
198	    vis_s: &mut [bool],
199	    vis_c: &mut [bool],
200	    start: usize,
201	) -> Path64 {
202	    let mut poly: Path64 = Vec::new();
203	    let mut in_s = true;
204	    let mut cur = start;
205	    vis_s[start] = true;
206	    if let Some(n) = s[start].neighbor {
207	        vis_c[n] = true;
208	    }
209	    poly.push(s[start].pt);
210	
211	    // Hard iteration cap so degenerate input can never hang us.
212	    let cap = 4 * (s.len() + c.len()) + 16;
213	    let mut steps = 0usize;
214	
215	    loop {
216	        steps += 1;
217	        if steps > cap {
218	            break;
219	        }
220	        let (nodes, entry) = if in_s { (s, s_entry) } else { (c, c_entry) };
221	        let fwd = entry[cur];
222	
223	        // Walk until the next crossing.
224	        loop {
225	            cur = if fwd { nodes[cur].next } else { nodes[cur].prev };
226	            steps += 1;
227	            if steps > cap {
228	                return poly;
229	            }
230	            if nodes[cur].intersect {
231	                break;
232	            }
233	            push_pt(&mut poly, nodes[cur].pt);
234	        }
235	
236	        // Mark the crossing pair visited and hop to the other polygon.
237	        if in_s {
238	            vis_s[cur] = true;
239	            if let Some(n) = nodes[cur].neighbor {
240	                vis_c[n] = true;
241	            }
242	        } else {
243	            vis_c[cur] = true;
244	            if let Some(n) = nodes[cur].neighbor {
245	                vis_s[n] = true;
246	            }
247	        }
248	        match nodes[cur].neighbor {
249	            Some(nidx) => {
250	                in_s = !in_s;
251	                cur = nidx;
252	            }
253	            None => break,
254	        }
255	        if in_s && cur == start {
256	            break; // closed the loop back at the start crossing
257	        }
258	        push_pt(&mut poly, if in_s { s[cur].pt } else { c[cur].pt });
259	    }
260	
261	    // Drop a duplicated closing vertex.
262	    if poly.len() > 1 && poly.first() == poly.last() {
263	        poly.pop();
264	    }
265	    poly
266	}
267	
268	#[derive(Clone, Copy)]
269	enum Op {
270	    Intersection,
271	    Union,
272	    Difference, // subjects minus clips
273	}
274	
275	/// Boolean operation between two simple polygons.
276	fn clip_pair(subj: &Path64, clip: &Path64, op: Op) -> Paths64 {
277	    let mut out: Paths64 = Vec::new();
278	    if subj.len() < 3 || clip.len() < 3 {
279	        return out; // degenerate input: nothing meaningful to compute
280	    }
281	
282	    let pd = build_lists(subj, clip);
283	    let has_crossings = pd.s.iter().any(|n| n.intersect);
284	
285	    if !has_crossings {
286	        // Disjoint or nested polygons: no tracing needed.
287	        let s_in_c = point_in_path(subj[0], clip);
288	        let c_in_s = point_in_path(clip[0], subj);
289	        match op {
290	            Op::Intersection => {
291	                if s_in_c {
292	                    out.push(subj.clone());
293	                } else if c_in_s {
294	                    out.push(clip.clone());
295	                }
296	            }
297	            Op::Union => {
298	                if s_in_c {
299	                    out.push(clip.clone());
300	                } else if c_in_s {
301	                    out.push(subj.clone());
302	                } else {
303	                    out.push(subj.clone());
304	                    out.push(clip.clone());
305	                }
306	            }
307	            Op::Difference => {
308	                // Nested clip would carve a hole; holes are ignored.
309	                if !s_in_c {
310	                    out.push(subj.clone());
311	                }
312	            }
313	        }
314	        return out;
315	    }
316	
317	    // Greiner–Hormann tracing with operation-specific entry/exit inversion:
318	    // intersection keeps flags, union inverts both lists, difference inverts
319	    // the subject list. Tracing then starts at every effective "entry"
320	    // crossing of the subject list.
321	    let (inv_s, inv_c) = match op {
322	        Op::Intersection => (false, false),
323	        Op::Union => (true, true),
324	        Op::Difference => (true, false),
325	    };
326	    let s_entry: Vec<bool> = pd.s.iter().map(|n| n.entry ^ inv_s).collect();
327	    let c_entry: Vec<bool> = pd.c.iter().map(|n| n.entry ^ inv_c).collect();
328	    let mut vis_s = vec![false; pd.s.len()];
329	    let mut vis_c = vec![false; pd.c.len()];
330	
331	    for i in 0..pd.s.len() {
332	        if !pd.s[i].intersect || vis_s[i] || !s_entry[i] {
333	            continue;
334	        }
335	        let poly = trace(&pd.s, &pd.c, &s_entry, &c_entry, &mut vis_s, &mut vis_c, i);
336	        if poly.len() >= 3 && area(&poly).abs() > 0.0 {
337	            out.push(poly);
338	        }
339	    }
340	    out
341	}
342	
343	/// Enforce the output convention: counter-clockwise (positive area).
344	fn ensure_ccw(paths: &mut Paths64) {
345	    for p in paths.iter_mut() {
346	        if area(p) < 0.0 {
347	            p.reverse();
348	        }
349	    }
350	}
351	
352	/// Intersection of all subject paths with all clip paths (pairwise).
353	pub fn intersect(subjects: &Paths64, clips: &Paths64, _fill_rule: FillRule) -> Paths64 {
354	    let mut out = Vec::new();
355	    for s in subjects {
356	        for c in clips {
357	            out.extend(clip_pair(s, c, Op::Intersection));
358	        }
359	    }
360	    ensure_ccw(&mut out);
361	    out
362	}
363	
364	/// Union of subject and clip paths (pairwise per subject×clip pair).
365	pub fn union_op(subjects: &Paths64, clips: &Paths64, _fill_rule: FillRule) -> Paths64 {
366	    let mut out = Vec::new();
367	    if clips.is_empty() {
368	        out.extend(subjects.iter().cloned());
369	    } else if subjects.is_empty() {
370	        out.extend(clips.iter().cloned());
371	    } else {
372	        for s in subjects {
373	            for c in clips {
374	                out.extend(clip_pair(s, c, Op::Union));
375	            }
376	        }
377	    }
378	    ensure_ccw(&mut out);
379	    out
380	}
381	
382	/// Subject paths minus the union of clip paths (clips applied sequentially).
383	pub fn difference(subjects: &Paths64, clips: &Paths64, _fill_rule: FillRule) -> Paths64 {
384	    let mut result = subjects.clone();
385	    for c in clips {
386	        let mut next = Vec::new();
387	        for s in &result {
388	            next.extend(clip_pair(s, c, Op::Difference));
389	        }
390	        result = next;
391	    }
392	    ensure_ccw(&mut result);
393	    result
394	}
395	
396	/// Symmetric difference: (subjects − clips) ∪ (clips − subjects).
397	pub fn xor(subjects: &Paths64, clips: &Paths64, fill_rule: FillRule) -> Paths64 {
398	    let mut out = difference(subjects, clips, fill_rule);
399	    out.extend(difference(clips, subjects, fill_rule));
400	    ensure_ccw(&mut out);
401	    out
402	}

